class BloomFilter:
    """
    A Bloom Filter implementation that uses a bit array and multiple hash functions.

    The bloom filter optimally calculates the size of the bit array and the number 
    of hash functions based on the desired false positive rate and the expected 
    number of items. This design allows for efficient membership testing with 
    reduced space complexity.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        if expected_items <= 0:
            raise ValueError("Expected items must be greater than 0.")
        if not (0 < false_positive_rate < 1):
            raise ValueError("False positive rate must be between 0 and 1.")

        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate optimal bit array size and number of hash functions
        self.size = self._optimal_size()
        self.hash_count = self._optimal_number_of_hashes()

        self.bit_array = [0] * self.size

    def _optimal_size(self) -> int:
        """Calculate the optimal size of the bit array."""
        size = - (self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2)
        return int(math.ceil(size))

    def _optimal_number_of_hashes(self) -> int:
        """Calculate the optimal number of hash functions."""
        return int(math.ceil((self.size / self.expected_items) * math.log(2)))

    def _hashes(self, item: str) -> list:
        """Generate multiple hash values for the given item."""
        hash_indices = []
        for i in range(self.hash_count):
            hash_result = hashlib.md5((item + str(i)).encode()).hexdigest()
            index = int(hash_result, 16) % self.size
            hash_indices.append(index)
        return hash_indices

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom filter."""
        for index in self._hashes(item):
            if self.bit_array[index] == 0:
                return False
        return True

