class BloomFilter:
    """
    A Bloom Filter implementation to efficiently test membership of items 
    with a controlled false positive rate. 
    Uses a bit array and multiple hash functions to reduce memory usage 
    while allowing for false positives.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.size = self._get_optimal_size(expected_items, false_positive_rate)
        self.hash_count = self._get_optimal_hash_count(self.size, expected_items)
        self.bit_array = [0] * self.size

    def _get_optimal_size(self, n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return max(1, int(-n * math.log(p) / (math.log(2) ** 2)))

    def _get_optimal_hash_count(self, m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, int((m / n) * math.log(2)))

    def _hashes(self, item: str):
        """Generate hash indices for the given item."""
        # Generate several hash values based on the item
        for i in range(self.hash_count):
            # Create a unique hash using hashlib
            hash_result = hashlib.sha256((item + str(i)).encode()).hexdigest()
            yield int(hash_result, 16) % self.size

    def add(self, item: str) -> None:
        """Add an item to the Bloom Filter."""
        for index in self._hashes(item):
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is possibly in the Bloom Filter."""
        return all(self.bit_array[index] for index in self._hashes(item))
